"""Repro script for issue: from_db_value not called for returning_fields on insert."""
import django
from django.conf import settings

settings.configure(
    DEBUG=True,
    DATABASES={
        'default': {
            'ENGINE': 'django.db.backends.sqlite3',
            'NAME': ':memory:',
        }
    },
    INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
    DEFAULT_AUTO_FIELD='django.db.models.AutoField',
    USE_TZ=True,
)
django.setup()

from django.db import models  # noqa: E402


class MyIntWrapper:
    def __init__(self, value):
        self.value = value

    def __repr__(self):
        return '<MyIntWrapper: %s>' % self.value

    def __eq__(self, other):
        if isinstance(other, MyIntWrapper):
            return self.value == other.value
        return self.value == other


class MyAutoField(models.BigAutoField):
    def from_db_value(self, value, expression, connection):
        if value is None:
            return None
        return MyIntWrapper(value)

    def get_prep_value(self, value):
        if value is None:
            return None
        return int(value)


class AutoModel(models.Model):
    id = MyAutoField(primary_key=True)

    class Meta:
        app_label = 'repro'


from django.db import connection  # noqa: E402

with connection.schema_editor() as se:
    se.create_model(AutoModel)

am = AutoModel.objects.create()
print('create() -> id =', repr(am.id))
assert isinstance(am.id, MyIntWrapper), 'FAIL: create() returned %r' % am.id

am_q = AutoModel.objects.first()
print('query    -> id =', repr(am_q.id))
assert isinstance(am_q.id, MyIntWrapper), 'FAIL: query returned %r' % am_q.id

ams = [AutoModel()]
AutoModel.objects.bulk_create(ams)
print('bulk     -> id =', repr(ams[0].id))
assert isinstance(ams[0].id, MyIntWrapper), 'FAIL: bulk_create returned %r' % ams[0].id

print('OK: all pathways return MyIntWrapper')

